INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('Weiterlesen', 'joomlaguide-read-more-de', '<p>Ein Blog zeigt den ganzen Text jedes Beitrags, und das ergibt eine lange Seite. Mit einem <em>Weiterlesen</em> zeigt er nur den ersten Teil, mit einem Link zum vollständigen Beitrag.</p><p>Die Kategorie <strong>Astronomie</strong>, ihre Beiträge <strong>Sternschnuppen</strong> und <strong>Meteore</strong> und der Menüeintrag <strong>Astronomie-Blog</strong> sind schon da. Sieh dir zuerst deine Website an, wenn du magst: Klicke in der Werkzeugleiste des Joomla Playground auf <strong>Site</strong> und dann im Main Menu auf <strong>Astronomie-Blog</strong>. Beide Beiträge zeigen ihren vollständigen Text.</p><p>Diese Tour folgt dem Tutorial <a href="https://guide.joomla.org/de/tutorials/inhaltsverwaltung/6-paginierung-weiterlesen/6-2-weiterlesen" target="_blank" rel="noopener">6.2 Weiterlesen</a> der Joomla-Benutzerdokumentation.</p>', 1, '["com_cpanel","com_content"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 6.2 Read More', 1, 1);
